const goal=6;
let round=0,edges=[],pop={},elapsed=0,stable=0,selected=null,selectedEdge='',editing=false,web=true,running=false,completed=false,pending=false,extinctId=null,score=0,charges=2,combo=0,lastLink=0,drag=null,suppressClick=false,lastSaved='',generation=0,rewarded=new Set(),bannerTimer=null;
