const exists=id=>id!==extinctId;
const live=id=>exists(id)&&pop[id]>0;
function stats(id,p=pop,list=edges){let intake=0,out=0;for(const [a,b,w] of list){if(p[a]>0&&p[b]>0&&exists(a)&&exists(b)){if(a===id)out+=w;if(b===id)intake+=w;}}const consumer=data[id].need>0,required=consumer?data[id].need+out:0;return{intake,out,required,hunger:consumer?Math.max(0,required-intake):0,surplus:consumer?Math.max(0,intake-required):0,pressure:consumer?0:Math.max(0,out-supply[id])};}
