function balance(){return all.filter(exists).every(id=>okay(id));}
function balanceValue(){const ids=all.filter(exists);return Math.round(ids.filter(id=>okay(id)).length/ids.length*100);}
function step(p){const q={...p};for(const id of all){if(!exists(id)||p[id]===0){q[id]=0;continue;}const s=stats(id,p);let delta=-.9*s.hunger+.9*s.surplus-.6*s.pressure;if(!delta){const target=data[id].need?60:supply[id]*10;delta=Math.max(-1.5,Math.min(1.5,target-p[id]));}q[id]=Math.max(0,Math.min(100,p[id]+delta));}return q;}
