function restore(input){if(!input||![6,7,8].includes(input.version))return false;clearedWorlds=new Set(input.version===8&&Array.isArray(input.clearedWorlds)?input.clearedWorlds.filter(id=>worlds.some(w=>w.id===id)):input.completed&&input.round===2?['forest']:[]);worldSaves=input.version===8&&input.worldSaves&&typeof input.worldSaves==='object'?Object.fromEntries(worlds.filter(w=>input.worldSaves[w.id]&&typeof input.worldSaves[w.id]==='object').map(w=>[w.id,input.worldSaves[w.id]])):{};const requested=input.version===8&&Number.isInteger(input.worldIndex)?Math.max(0,Math.min(2,input.worldIndex)):0;configureWorld(Math.min(requested,maxUnlockedWorld()));const v={...input,...(worldSaves[world().id]||{})};if(!Number.isInteger(v.round)||v.round<0||v.round>2)return false;round=v.round;roundScore=Number.isFinite(v.roundScore)?Math.max(0,Math.floor(v.roundScore)):0;roundElapsed=Number.isFinite(v.roundElapsed)?Math.max(0,Math.floor(v.roundElapsed)):0;roundStart=v.roundStart&&typeof v.roundStart==='object'&&v.roundStart.worldId===world().id&&v.roundStart.round===round?v.roundStart:null;extinctId=round===2&&['rabbit','mouse','hopper','snail'].includes(v.extinctId)?v.extinctId:null;edges=(Array.isArray(v.edges)?v.edges:[]).filter(e=>Array.isArray(e)&&all.includes(e[0])&&all.includes(e[1])&&diets[e[1]]?.includes(e[0])&&Number.isInteger(e[2])&&e[2]>0&&e[2]<=8&&exists(e[0])&&exists(e[1])).map(e=>e.slice());supply=Object.fromEntries(Object.keys(baseSupply).map(id=>[id,Number.isInteger(v.supply?.[id])?Math.max(3,Math.min(8,v.supply[id])):baseSupply[id]]));pop=Object.fromEntries(all.map(id=>[id,Number.isFinite(v.pop?.[id])?Math.max(0,Math.min(100,v.pop[id])):data[id].need?60:supply[id]*10]));if(extinctId)pop[extinctId]=0;elapsed=Number.isInteger(input.elapsed)?Math.max(0,input.elapsed):0;stable=input.version>=7&&Number.isInteger(v.stable)?Math.max(0,Math.min(goal,v.stable)):0;score=Number.isInteger(input.score)?Math.max(0,input.score):0;charges=Number.isInteger(v.charges)?Math.max(0,Math.min(2,v.charges)):2;completed=!!v.completed&&round===2;if(completed)clearedWorlds.add(world().id);web=v.web!==false;freeExploring=input.version===8&&!!v.freeExploring;rewarded=new Set(Array.isArray(v.rewarded)?v.rewarded.filter(x=>typeof x==='string'&&x.length<40):[]);tutorialDone=!!input.tutorialDone;tutorialStep=input.version>=7&&Number.isInteger(input.tutorialStep)?Math.max(0,Math.min(10,input.tutorialStep)):0;if(!tutorialDone&&input.version<8&&tutorialStep>=6)tutorialStep=7;needsRuleHelp=input.version===6||!!input.needsRuleHelp;helpOpen=needsRuleHelp;helpWasRunning=false;worldWinOpen=completed&&!freeExploring&&!needsRuleHelp;worldMenuOpen=false;edgeAnchor=null;retargetKey='';edgeDraft=null;pending=false;running=false;selected=null;selectedEdge='';editing=false;return true;}
