function changed(t){stable=0;render();toast(t);save();}
function prepareFreeExplore(){if(!completed||!extinctId)return false;const returned=extinctId;extinctId=null;pop[returned]=60;const foods=[...diets[returned]].sort((a,b)=>(supply[b]-stats(b).out)-(supply[a]-stats(a).out));let remaining=data[returned].need;for(const food of foods){const used=stats(food).out,amount=Math.min(remaining,Math.max(0,8-used));if(!amount)continue;supply[food]=Math.max(supply[food],used+amount);if(pop[food]===0)pop[food]=supply[food]*10;edges.push([food,returned,amount]);rewarded.add(food+'|'+returned);remaining-=amount;if(!remaining)break;}if(remaining){const food=foods[0];if(pop[food]===0)pop[food]=supply[food]*10;const e=edges.find(e=>e[0]===food&&e[1]===returned);if(e)e[2]+=remaining;else edges.push([food,returned,remaining]);rewarded.add(food+'|'+returned);}return true;}
function tutorialOn(){return !tutorialDone;}
function tutorialFree(){return tutorialOn()&&tutorialStep===7;}
function tutorialObject(id){const name=data[id].name;return name+((name.charCodeAt(name.length-1)-44032)%28?'을':'를');}
