function practiceHint(){
 if(balance())return{title:'먹이그물 완성!',reason:'이제 균형이 유지되는지 확인해요.',cue:'✓ 균형을 맞췄어요',control:'[data-tutorial-next]'};
 if(editing&&edgeDraft!==null){const e=edges.find(([a,b])=>a+'|'+b===selectedEdge);if(e){const target=Math.max(0,Math.min(8,e[2]+stats(e[1]).required-stats(e[1]).intake)),amount=edgeDraft;return{title:amount===target?'확인을 눌러요.':`${amount<target?'+':'−'}를 눌러 ${target}칸으로 맞춰요.`,reason:amount===target?'고른 양만큼 먹이를 주는 거예요.':amount>target?'먹이가 남으면 개체 수가 늘어요.':stats(e[1]).out?'먹히는 만큼 먹이가 더 필요해요.':'먹이가 부족하면 개체 수가 줄어요.',cue:`${data[e[1]].name} 먹이 ${stats(e[1]).intake} / ${stats(e[1]).required}칸`,edge:selectedEdge,control:amount===target?'[data-line-apply]':amount<target?'[data-plus]':'[data-minus]'};}}
 const hungry=all.find(id=>data[id].need&&(stats(id).hunger||stats(id).surplus));
 if(hungry){const s=stats(hungry),foods=edges.filter(e=>e[1]===hungry),food=foods.find(e=>s.hunger?e[2]<8:e[2]>0),cue=`${data[hungry].name}: 기본 2 + 먹힘 ${s.out} = ${s.required}칸`;
  const reason=s.out?'먹히는 만큼 먹이가 더 필요해요.':s.surplus?'먹이가 남으면 개체 수가 늘어요.':'먹이가 부족하면 개체 수가 줄어요.';
  if(!food)return selected===hungry?{title:'먹을 생물을 골라요.',reason:'먹이길이 없으면 배고파요.',cue,targets:newFoods(hungry)}:{title:`${tutorialObject(hungry)} 눌러요.`,reason,cue,node:hungry};
  return{title:'먹이선의 숫자를 눌러요.',reason,cue,edge:food[0]+'|'+hungry};
 }
 const plant=all.find(id=>!data[id].need&&stats(id).pressure),cue=plant?`${data[plant].name}: 생산 ${supply[plant]} / 필요 ${stats(plant).out}칸`:'';
 if(plant)return selected===plant?{title:`+를 눌러 ${stats(plant).out}칸으로 맞춰요.`,reason:'먹히는 만큼 더 자라야 해요.',cue,node:plant,control:'[data-supply-plus]'}:{title:`${tutorialObject(plant)} 눌러요.`,reason:'먹히는 양보다 덜 자라고 있어요.',cue,node:plant};
 return{title:'먹이가 필요한 생물을 찾아요.',reason:'모든 생물이 살아야 균형을 이뤄요.',cue:''};
}
function tutorialTarget(id){if(tutorialFree()){const h=practiceHint();return h.node===id||h.targets?.includes(id);}if(tutorialStep===6)return selected==='rabbit'?diets.rabbit.includes(id):id==='rabbit';return tutorialStep===1?id==='fox':tutorialStep===2?id==='rabbit':false;}
