function renderTutorial(){const coach=$('[data-tutorial]');coach.dataset.intro=String(helpOpen||tutorialStep===0);coach.dataset.guideHelp=String(helpOpen);root.classList.toggle('fg-practising',tutorialOn()&&tutorialStep>0&&!helpOpen);coach.hidden=tutorialDone&&!helpOpen;root.classList.toggle('fg-tutorial-active',!coach.hidden);const ready=tutorialFree()&&balance(),hint=tutorialFree()?practiceHint():null;const purposes=['먹이가 부족한 동물들을 도와줘요.','먹는 동물부터 고르는 거예요.','여우가 토끼를 먹어요.','숫자는 먹는 양을 뜻해요.','여우에게 먹이 2칸이 필요해요.','여우가 먹을 양을 정하는 거예요.','먹히는 토끼도 먹이를 더 먹어야 해요.'];const titles=['먹이길을 직접 이어봐요!','여우를 눌러요.','토끼를 눌러요.','선 위의 1을 눌러요.','+를 한 번 눌러요.','확인을 눌러요.','토끼를 눌러요.','직접 이어봐요.'];
$('[data-tutorial-step]').textContent=helpOpen?'조작법과 균형 규칙':tutorialStep===0?'처음 배우기':tutorialStep>=6?'스스로 도전':`함께 연습 ${tutorialStep} / 5`;$('[data-tutorial-title]').textContent=helpOpen?'기본 2칸 + 먹히는 양':hint?hint.title:tutorialStep===6&&selected==='rabbit'?'먹을 식물을 골라요.':titles[tutorialStep]||titles[7];$('[data-tutorial-body]').textContent=helpOpen?'화살표는 먹히는 생물 → 먹는 생물, 먹이와 에너지의 전달 방향이에요. 연결은 먹는 동물을 먼저 고르고 먹이를 선택하세요. 선에서 양을 바꾼 뒤 확인, 0칸은 연결 끊기예요. 식물을 눌러 생산량을 조절하세요.':hint?hint.reason:tutorialStep===6&&selected==='rabbit'?'토끼는 풀과 잎을 먹어요.':purposes[tutorialStep]||'';const exampleFood=diets.fox[0];$('[data-rule-consumer-example]').textContent=`${subjectName(exampleFood)} 1칸 먹히면, 먹이 3칸을 주세요.`;$('[data-guide-food-name]').textContent=data[exampleFood].name;$('[data-guide-eater-name]').textContent=data.fox.name;for(const [sel,id] of [['[data-guide-food-sprite]',exampleFood],['[data-guide-eater-sprite]','fox']]){const s=data[id].sprite;$(sel).style.backgroundPosition=`${s%4*100/3}% ${Math.floor(s/4)*100}%`;} $('[data-tutorial-body]').hidden=false;$('[data-tutorial-example]').hidden=!helpOpen;$('[data-rule-example]').hidden=!helpOpen;$('[data-seed-help]').hidden=!helpOpen;const list=$('[data-practice-checks]');list.hidden=true;if(!list.hidden){const animals=all.filter(id=>data[id].need),plants=all.filter(id=>!data[id].need),foodOkay=animals.every(id=>!stats(id).hunger&&!stats(id).surplus),plantOkay=plants.every(id=>!stats(id).pressure);list.replaceChildren();for(const [ok,text] of [[foodOkay,'동물: 기본 2칸 + 먹히는 양'],[plantOkay,'생산자: 소비 이상으로 생산']]){const li=document.createElement('li');li.textContent=(ok?'✓ ':'○ ')+text;li.dataset.done=String(ok);list.append(li);}const s=stats('rabbit'),tip=document.createElement('li');tip.textContent=`토끼 먹이 ${s.intake} / 필요 ${s.required}칸`;list.append(tip);}
const cue=$('[data-guide-cue]');cue.hidden=helpOpen||tutorialStep===0;cue.textContent=hint?hint.cue:tutorialStep===2||tutorialStep===3?'토끼 → 여우\n먹이·에너지':tutorialStep===4||tutorialStep===5?'여우 먹이: 2칸':tutorialStep===6?'토끼: 기본 2 + 먹힘 2 = 4칸':'';if(!cue.textContent)cue.hidden=true;for(const sel of ['[data-plus]','[data-minus]','[data-line-apply]','[data-supply-plus]','[data-tutorial-next]'])$(sel).classList.remove('fg-guide-control');const control=hint?.control||({4:'[data-plus]',5:'[data-line-apply]'}[tutorialStep]);if(control)$(control).classList.add('fg-guide-control');$('[data-tutorial-next]').disabled=!helpOpen&&tutorialStep>0&&!ready;$('[data-tutorial-next]').textContent=helpOpen?'닫고 계속':tutorialStep===0?'해보기':ready?'게임 시작':'화면에서 직접 해보세요';$('[data-tutorial-skip]').hidden=helpOpen;$('[data-tutorial-skip]').textContent='연습 건너뛰기';}
function guideNext(){if(helpOpen){if(needsRuleHelp){needsRuleHelp=false;tutorialDone=true;tutorialStep=10;worldWinOpen=completed&&!freeExploring;}helpOpen=false;running=helpWasRunning;render();save();return;}if(tutorialStep===0){tutorialStep=1;render();toast('먹는 동물인 여우를 먼저 선택하세요.');save();}else if(tutorialFree()&&balance())finishTutorial(true);}
function showHelp(){if(tutorialOn())return;helpWasRunning=running;running=false;helpOpen=true;editing=false;edgeDraft=null;selected=null;selectedEdge='';retargetKey='';render();}
function choose(id){if(!exists(id))return;if(tutorialOn()&&!tutorialFree()){if(tutorialStep===1&&id==='fox'){selected='fox';tutorialStep=2;render();save();return;}if(tutorialStep===2&&id==='rabbit'){connect('rabbit','fox');return;}if(tutorialStep===2&&id==='fox'){selected='fox';render();return;}if(tutorialStep===6){if(id==='rabbit'){selected=selected==='rabbit'?null:'rabbit';render();save();}else if(selected==='rabbit')connect(id,'rabbit');}return;}
if(pop[id]===0){selected=id;editing=false;edgeDraft=null;selectedEdge='';render();toast(`${data[id].name}의 개체가 사라졌어요. 회복으로 도와주세요.`);return;}if(!selected||!data[selected].need){selected=id;selectedEdge='';editing=false;edgeDraft=null;edgeAnchor=null;render();toast(data[id].need?`${data[id].name}의 먹이를 골라주세요.`:`${subjectName(id)} 충분히 자라도록 도와주세요.`);}else if(selected===id){selected=null;if(retargetKey){const [a,b]=retargetKey.split('|');retargetKey='';openEdge(a,b);}else{render();toast('먹이그물의 균형을 맞춰주세요.');}}else if(live(selected))connect(id,selected);}
function relationText(a,b){const word=data[a].name,post=(word.charCodeAt(word.length-1)-44032)%28?'을':'를';return `${data[b].name}가 ${word}${post} 먹어요`;}
function newFoods(hunter){return (diets[hunter]||[]).filter(food=>live(food)&&(!retargetKey||!edges.some(e=>e[0]===food&&e[1]===hunter)||retargetKey===food+'|'+hunter));}
