function renderEditor(){const active=edges.find(([a,b])=>a+'|'+b===selectedEdge),box=$('[data-line-editor]');box.hidden=!editing||!active;if(!active)return;const [a,b]=active,w=edgeDraft??active[2],preview=edges.filter(e=>e!==active);if(w>0)preview.push([a,b,w]);const food=stats(a,pop,preview),eater=stats(b,pop,preview);$('[data-line-title]').textContent=relationText(a,b);$('[data-line-amount]').textContent=w+'칸';$('[data-line-effect]').textContent=w===0?'확인하면 이 선이 끊어져요.':data[a].need?`${data[b].name}: 먹이 ${eater.intake}/${eater.required}칸 · ${data[a].name}: 기본 2 + 먹힘 ${food.out} = 필요 ${food.required}칸 (현재 ${food.intake}칸)`:`${data[b].name}: 먹이 ${eater.intake}/${eater.required}칸 · ${data[a].name}: 소비 ${food.out}/생산 ${supply[a]}칸`;$('[data-plus]').disabled=w>=8||tutorialOn()&&!tutorialFree()&&(![4,7].includes(tutorialStep)||tutorialStep===7&&w>=4);$('[data-minus]').disabled=w<=0||tutorialOn()&&!tutorialFree();$('[data-line-apply]').disabled=tutorialOn()&&!tutorialFree()&&!(tutorialStep===5&&w===2||tutorialStep===7&&w===4);$('[data-disconnect]').disabled=tutorialOn()&&!tutorialFree();$('[data-retarget]').disabled=tutorialOn()&&!tutorialFree()||!(diets[b]||[]).some(food=>live(food)&&!edges.some(e=>e[0]===food&&e[1]===b));$('[data-line-close]').disabled=tutorialOn()&&!tutorialFree();positionEditor();}
