function positionEditor(){const box=$('[data-line-editor]');if(box.hidden||!edgeAnchor)return;const r=root.getBoundingClientRect(),q=box.getBoundingClientRect(),dock=$('.fg-dock').getBoundingClientRect(),coach=$('[data-tutorial]').getBoundingClientRect(),minY=$('.fg-field').getBoundingClientRect().top-r.top,maxY=Math.max(minY,dock.top-r.top-q.height-10);const candidates=[[edgeAnchor.x-q.width/2,edgeAnchor.y+20],[edgeAnchor.x-q.width/2,edgeAnchor.y-q.height-20],[edgeAnchor.x+25,edgeAnchor.y-q.height/2],[edgeAnchor.x-q.width-25,edgeAnchor.y-q.height/2],[r.width-q.width-18,minY],[18,minY]];let best=null;for(const [x,y] of candidates){const left=Math.max(12,Math.min(r.width-q.width-12,x)),top=Math.max(minY,Math.min(maxY,y));let cost=Math.hypot(left+q.width/2-edgeAnchor.x,top+q.height/2-edgeAnchor.y);if((tutorialOn()||helpOpen)&&left+r.left<coach.right+10&&left+r.left+q.width>coach.left-10&&top+r.top<coach.bottom+10&&top+r.top+q.height>coach.top-10)cost+=10000;if(!best||cost<best.cost)best={left,top,cost};}box.style.left=best.left+'px';box.style.top=best.top+'px';}

