function applySaved(v){if(!restore(v))return false;generation++;clearTimeout(bannerTimer);$('[data-banner]').hidden=true;prepareFreeExplore();pending=v.version>=7&&!!v.pending&&!completed&&round<2;if(tutorialOn()){if(tutorialStep===2)selected='fox';if([4,5].includes(tutorialStep)){const key='rabbit|fox',active=edges.find(([a,b])=>a+'|'+b===key);if(active){selectedEdge=key;edgeDraft=tutorialStep===5?2:active[2];editing=true;const r=root.getBoundingClientRect();edgeAnchor={x:r.width/2,y:r.height*.45};}else tutorialStep=0;}if(tutorialStep>=8)tutorialStep=7;}if(!roundStart&&!tutorialOn())captureRoundStart();render();if(pending){announce('균형 회복! +100','먹이그물을 지켰어요!');const token=generation;setTimeout(()=>{if(token===generation)enterNextPhase();},2200);}return true;}
